3: import { env, pipeline, type ProgressInfo } from '@huggingface/transformers';
4: 
5: env.allowLocalModels = false;
6: env.useBrowserCache = true;
7: 
8: const ctx = self as unknown as DedicatedWorkerGlobalScope;
9: 
10: const detectDevice = async (): Promise<'webgpu' | 'wasm'> => {
11:   const nav = navigator as Navigator & { gpu?: { requestAdapter: () => Promise<unknown> } };
12:   try {
13:     if (nav.gpu && (await nav.gpu.requestAdapter())) {
14:       return 'webgpu';
15:     }
16:   } catch {
17:     /* fall through */
18:   }
19:   return 'wasm';
20: };
21: 
22: const transcriberReady = (async () => {
23:   const device = await detectDevice();
