26:     'onnx-community/whisper-small',
27:     {
28:       device,
29:       dtype: device === 'webgpu' ? 'q4' : 'q8',
30:       progress_callback: (info: ProgressInfo) => {
31:         if (info.status === 'progress_total') {
32:           ctx.postMessage({ type: 'progress', progress: info.progress });
